#!/usr/bin/env python3
import sys
import os
import re
import html as htmlmod
from html.parser import HTMLParser
from urllib.parse import urlparse, urljoin

VERSION = "htmlq 0.4.0"

VOID_TAGS = {
    'area','base','br','col','embed','hr','img','input','keygen','link','meta',
    'param','source','track','wbr','command'
}
HEAD_TAGS = {'base','basefont','bgsound','link','meta','title','style','script','noscript','template'}
P_CLOSERS = {
    'address','article','aside','blockquote','div','dl','fieldset','footer','form',
    'h1','h2','h3','h4','h5','h6','header','hgroup','hr','main','menu','nav','ol',
    'p','pre','section','table','ul','center','dir','listing','plaintext'
}
LINK_HREF_TAGS = {'a','area','link'}

class Node:
    __slots__ = ('kind','tag','attrs','children','parent','data')
    def __init__(self, kind, tag=None, attrs=None, data=None):
        self.kind = kind
        self.tag = tag
        self.attrs = attrs or {}
        self.children = []
        self.parent = None
        self.data = data
    def append(self, child):
        child.parent = self
        self.children.append(child)
    def remove_child(self, child):
        try:
            self.children.remove(child)
            child.parent = None
        except ValueError:
            pass


def normalize_attrs(attrs):
    out = {}
    for k, v in attrs:
        if k is None:
            continue
        name = k.lower()
        if name in out:
            continue
        out[name] = '' if v is None else v
    return out

class TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.doc = Node('document')
        self.html = None
        self.head = None
        self.body = None
        self.stack = [self.doc]
        self.head_started = False
        self.head_closed = False
        self.body_started = False
        self.body_closed = False
        self.after_html = False
        self.in_foreign = 0

    def ensure_html(self, attrs=None):
        if self.html is None:
            self.html = Node('element', 'html', attrs or {})
            self.doc.append(self.html)
            self.stack = [self.doc, self.html]
        else:
            if attrs:
                for k, v in attrs.items():
                    if k not in self.html.attrs:
                        self.html.attrs[k] = v
            if self.html not in self.stack:
                self.stack = [self.doc, self.html]
        return self.html

    def ensure_head(self):
        self.ensure_html()
        if self.head is None:
            self.head = Node('element', 'head', {})
            # head should precede body; if body was created, insert before it.
            if self.body is not None and self.body in self.html.children:
                idx = self.html.children.index(self.body)
                self.head.parent = self.html
                self.html.children.insert(idx, self.head)
            else:
                self.html.append(self.head)
        return self.head

    def ensure_body(self, attrs=None):
        self.ensure_html()
        if self.head is None:
            self.ensure_head()
            self.head_closed = True
        if self.body is None:
            self.body = Node('element', 'body', attrs or {})
            self.html.append(self.body)
        else:
            if attrs:
                for k, v in attrs.items():
                    if k not in self.body.attrs:
                        self.body.attrs[k] = v
        self.body_started = True
        self.body_closed = False
        if self.stack[-1] is self.doc or self.stack[-1] is self.html or self.body not in self.stack:
            self.stack = [self.doc, self.html, self.body]
        return self.body

    def close_until(self, tag):
        for i in range(len(self.stack)-1, 0, -1):
            n = self.stack[i]
            if n.kind == 'element' and n.tag == tag:
                self.stack = self.stack[:i]
                return True
        return False

    def has_open(self, tag):
        return any(n.kind == 'element' and n.tag == tag for n in self.stack)

    def top_tag(self):
        n = self.stack[-1]
        return n.tag if n.kind == 'element' else None

    def pop_tag_if_open(self, tag):
        for i in range(len(self.stack)-1, 0, -1):
            if self.stack[i].kind == 'element' and self.stack[i].tag == tag:
                self.stack = self.stack[:i]
                return True
        return False

    def pop_until_one_of(self, tags):
        for i in range(len(self.stack)-1, 0, -1):
            if self.stack[i].kind == 'element' and self.stack[i].tag in tags:
                self.stack = self.stack[:i]
                return True
        return False

    def append_to_current(self, node):
        if self.stack[-1] is self.doc:
            self.ensure_body()
        self.stack[-1].append(node)

    def prepare_start(self, tag):
        # Common implied end tags. This is intentionally small but covers the
        # HTML constructs users commonly query from the command line.
        if tag in P_CLOSERS and self.has_open('p'):
            self.close_until('p')
        if tag == 'li' and self.has_open('li'):
            self.close_until('li')
        if tag in ('dt','dd') and any(self.has_open(t) for t in ('dt','dd')):
            self.pop_until_one_of({'dt','dd'})
        if tag == 'option' and self.has_open('option'):
            self.close_until('option')
        if tag == 'optgroup':
            if self.has_open('option'):
                self.close_until('option')
            if self.has_open('optgroup'):
                self.close_until('optgroup')
        if tag in ('rt','rp') and any(self.has_open(t) for t in ('rt','rp')):
            self.pop_until_one_of({'rt','rp'})

        if tag in ('tbody','thead','tfoot'):
            if self.has_open('td'):
                self.close_until('td')
            if self.has_open('th'):
                self.close_until('th')
            if self.has_open('tr'):
                self.close_until('tr')
            # close a previous section, but do not pop the table itself
            for i in range(len(self.stack)-1, 0, -1):
                if self.stack[i].kind == 'element' and self.stack[i].tag in ('tbody','thead','tfoot'):
                    self.stack = self.stack[:i]
                    break
        if tag == 'tr':
            if self.has_open('td'):
                self.close_until('td')
            if self.has_open('th'):
                self.close_until('th')
            if self.has_open('tr'):
                self.close_until('tr')
            # Insert an implicit tbody for rows directly under a table.
            if self.top_tag() == 'table':
                tbody = Node('element', 'tbody', {})
                self.stack[-1].append(tbody)
                self.stack.append(tbody)
        if tag in ('td','th'):
            if self.has_open('td'):
                self.close_until('td')
            if self.has_open('th'):
                self.close_until('th')
            if not self.has_open('tr'):
                if self.top_tag() == 'table':
                    tbody = Node('element', 'tbody', {})
                    self.stack[-1].append(tbody)
                    self.stack.append(tbody)
                tr = Node('element', 'tr', {})
                self.stack[-1].append(tr)
                self.stack.append(tr)

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attrs = normalize_attrs(attrs)
        if tag == 'html':
            self.ensure_html(attrs)
            return
        if tag == 'head':
            if not self.body_started and not self.head_closed:
                self.ensure_html()
                h = self.ensure_head()
                self.head_started = True
                self.stack = [self.doc, self.html, h]
            else:
                self.ensure_body()
            return
        if tag == 'body':
            self.ensure_html()
            self.ensure_head()
            self.head_closed = True
            self.ensure_body(attrs)
            self.stack = [self.doc, self.html, self.body]
            return

        # If we are in the head and see a non-head element, close the head first.
        if self.stack[-1] is self.head and tag not in HEAD_TAGS:
            self.stack = [self.doc, self.html]
            self.head_closed = True

        if not self.body_started:
            if tag in HEAD_TAGS and not self.head_closed:
                self.ensure_html()
                h = self.ensure_head()
                self.head_started = True
                if h not in self.stack:
                    self.stack = [self.doc, self.html, h]
                elem = Node('element', tag, attrs)
                h.append(elem)
                if tag not in VOID_TAGS:
                    self.stack.append(elem)
                return
            else:
                # Before body: initial non-body content starts body. If an
                # explicit head was just closed, inter-element whitespace may
                # have been placed under html already; real content starts body.
                self.ensure_head()
                self.head_closed = True
                self.ensure_body()

        if self.body_closed:
            self.ensure_body()
        self.prepare_start(tag)
        elem = Node('element', tag, attrs)
        self.append_to_current(elem)
        if tag not in VOID_TAGS:
            self.stack.append(elem)

    def handle_startendtag(self, tag, attrs):
        tag_l = tag.lower()
        # In HTML mode the slash is ignored for non-void tags. In foreign
        # content browsers close self-closing tags; this simple approximation
        # is useful for SVG/MathML snippets while preserving <div/> behavior.
        foreign = any(n.kind == 'element' and n.tag in ('svg','math') for n in self.stack)
        self.handle_starttag(tag_l, attrs)
        if tag_l not in VOID_TAGS and foreign:
            self.handle_endtag(tag_l)

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag == 'br':
            self.handle_starttag('br', [])
            return
        if tag in VOID_TAGS:
            return
        if tag == 'head':
            self.close_until('head')
            self.head_closed = True
            if self.html is not None:
                self.stack = [self.doc, self.html]
            return
        if tag == 'body':
            if self.body is not None:
                self.close_until('body')
                self.body_closed = True
                if self.html is not None:
                    self.stack = [self.doc, self.html]
            return
        if tag == 'html':
            if self.html is not None:
                # After </html>, further character data is still commonly
                # associated with the body by html5 parsers; comments are not.
                self.stack = [self.doc, self.html]
                self.after_html = True
                self.body_closed = True
            return
        if tag == 'p' and not self.has_open('p') and self.body_started and not self.body_closed:
            # Stray </p> inside body inserts an empty paragraph in HTML5.
            p = Node('element', 'p', {})
            self.append_to_current(p)
            return
        # Closing a table closes open cells/rows/sections too by popping until table.
        self.close_until(tag)

    def handle_data(self, data):
        if data == '':
            return
        if not self.body_started:
            if self.stack[-1] is self.head:
                self.stack[-1].append(Node('text', data=data))
            elif data.strip() == '':
                # Leading whitespace before html/head/body is ignored. After an
                # explicit head, whitespace between head and body belongs to html.
                if self.head_closed and self.html is not None:
                    self.html.append(Node('text', data=data))
            else:
                self.ensure_head(); self.head_closed = True; self.ensure_body()
                self.body.append(Node('text', data=data))
            return
        if self.body_closed:
            # Text after </body> or </html> is reparented into body.
            if self.body is not None:
                self.body.append(Node('text', data=data))
            return
        self.append_to_current(Node('text', data=data))

    def handle_comment(self, data):
        if not self.body_started:
            if self.stack[-1] is self.head:
                self.stack[-1].append(Node('comment', data=data))
            elif self.head_closed and self.html is not None:
                self.html.append(Node('comment', data=data))
            # Comments before the document element/body are dropped.
            return
        if self.body_closed:
            return
        self.append_to_current(Node('comment', data=data))

    def handle_decl(self, decl):
        # Doctypes are not included when serializing selected elements.
        pass

    def unknown_decl(self, data):
        pass

    def close(self):
        super().close()
        self.ensure_html()
        self.ensure_head()
        if self.body is None:
            self.ensure_body()
        return self.doc


def parse_html(data):
    b = TreeBuilder()
    b.feed(data)
    return b.close()

# ---------------- CSS selector parsing and matching ----------------
class SelectorParseError(Exception):
    pass

_IDENT_CHARS = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-')

class CSSParser:
    def __init__(self, s):
        self.s = s
        self.i = 0
        self.n = len(s)

    def eof(self): return self.i >= self.n
    def peek(self): return '' if self.eof() else self.s[self.i]
    def skip_ws(self):
        had = False
        while not self.eof() and self.s[self.i].isspace():
            self.i += 1; had = True
        return had

    def parse_selector_list(self):
        sels = []
        self.skip_ws()
        if self.eof():
            raise SelectorParseError()
        while True:
            sels.append(self.parse_complex(stop_chars={','}))
            self.skip_ws()
            if self.peek() == ',':
                self.i += 1
                self.skip_ws()
                if self.eof():
                    raise SelectorParseError()
                continue
            if not self.eof():
                raise SelectorParseError()
            break
        return sels

    def parse_complex(self, stop_chars=None):
        stop_chars = stop_chars or set()
        parts = []
        combinator = None
        expect_compound = True
        while True:
            ws = self.skip_ws()
            ch = self.peek()
            if self.eof() or ch in stop_chars or ch == ')':
                if expect_compound and combinator is not None:
                    raise SelectorParseError()
                break
            if not expect_compound and ws:
                combinator = ' '
                expect_compound = True
            ch = self.peek()
            if ch in ('>','+','~'):
                if expect_compound:
                    raise SelectorParseError()
                combinator = ch
                self.i += 1
                expect_compound = True
                continue
            comp = self.parse_compound()
            parts.append((combinator, comp))
            combinator = None
            expect_compound = False
        if not parts:
            raise SelectorParseError()
        return parts

    def parse_compound(self):
        comp = {'tag': None, 'universal': False, 'never': False, 'ids': [], 'classes': [], 'attrs': [], 'pseudos': []}
        started = False
        # Type selector / universal / namespace-ish selector
        if self.peek() == '*':
            self.i += 1
            if self.peek() == '|':
                self.i += 1
                name = self.parse_ident(required=True)
                comp['tag'] = name
            else:
                comp['universal'] = True
            started = True
        elif self.peek() == '|':
            # Empty namespace: valid, but in these HTML documents it matches no elements.
            self.i += 1
            name = self.parse_ident(required=True)
            comp['tag'] = name
            comp['never'] = True
            started = True
        elif self.is_ident_start(self.peek()):
            name = self.parse_ident(required=True)
            if self.peek() == '|':
                # Namespaces other than *| and | require a prefix map; htmlq panics.
                raise SelectorParseError()
            comp['tag'] = name
            started = True
        while not self.eof():
            ch = self.peek()
            if ch == '#':
                self.i += 1
                comp['ids'].append(self.parse_ident(required=True))
                started = True
            elif ch == '.':
                self.i += 1
                comp['classes'].append(self.parse_ident(required=True))
                started = True
            elif ch == '[':
                comp['attrs'].append(self.parse_attr_selector())
                started = True
            elif ch == ':':
                comp['pseudos'].append(self.parse_pseudo())
                started = True
            else:
                break
        if not started:
            raise SelectorParseError()
        return comp

    def is_ident_start(self, ch):
        return bool(ch) and (ch.isalpha() or ch == '_' or ch == '-' or ch == '\\' or ord(ch) >= 0x80)

    def parse_ident(self, required=False):
        out = []
        while not self.eof():
            ch = self.peek()
            if ch == '\\':
                out.append(self.parse_escape())
            elif ch in _IDENT_CHARS or ord(ch) >= 0x80:
                out.append(ch); self.i += 1
            else:
                break
        if required and not out:
            raise SelectorParseError()
        return ''.join(out)

    def parse_escape(self):
        self.i += 1
        if self.eof():
            return ''
        # CSS hex escape, up to 6 hex digits, optional trailing whitespace.
        j = self.i
        hexs = ''
        while not self.eof() and len(hexs) < 6 and self.s[self.i] in '0123456789abcdefABCDEF':
            hexs += self.s[self.i]; self.i += 1
        if hexs:
            if not self.eof() and self.s[self.i].isspace():
                self.i += 1
            try:
                return chr(int(hexs, 16))
            except Exception:
                return ''
        ch = self.s[self.i]
        self.i += 1
        return ch

    def parse_string(self):
        quote = self.peek()
        if quote not in ('"', "'"):
            raise SelectorParseError()
        self.i += 1
        out = []
        while not self.eof():
            ch = self.peek()
            if ch == quote:
                self.i += 1
                return ''.join(out)
            if ch == '\\':
                out.append(self.parse_escape())
            else:
                out.append(ch); self.i += 1
        raise SelectorParseError()

    def parse_attr_selector(self):
        if self.peek() != '[': raise SelectorParseError()
        self.i += 1
        self.skip_ws()
        name = self.parse_attr_name()
        if not name: raise SelectorParseError()
        self.skip_ws()
        op = None; value = None; flag = None
        if self.peek() == ']':
            self.i += 1
            return (name.lower(), op, value, flag)
        # operator
        two = self.s[self.i:self.i+2]
        if two in ('~=','|=','^=','$=','*='):
            op = two; self.i += 2
        elif self.peek() == '=':
            op = '='; self.i += 1
        else:
            raise SelectorParseError()
        self.skip_ws()
        if self.peek() in ('"', "'"):
            value = self.parse_string()
        else:
            value = self.parse_attr_value()
            if value == '':
                raise SelectorParseError()
        self.skip_ws()
        if self.peek() and self.peek() not in ']':
            # CSS4 case-sensitivity flag.
            flag = self.parse_ident(required=True).lower()
            if flag not in ('i','s'):
                raise SelectorParseError()
            self.skip_ws()
        if self.peek() != ']':
            raise SelectorParseError()
        self.i += 1
        return (name.lower(), op, value, flag)

    def parse_attr_name(self):
        out = []
        while not self.eof():
            ch = self.peek()
            if ch == '\\': out.append(self.parse_escape())
            elif ch.isalnum() or ch in '_-:': out.append(ch); self.i += 1
            elif ord(ch) >= 0x80: out.append(ch); self.i += 1
            else: break
        return ''.join(out)

    def parse_attr_value(self):
        out = []
        while not self.eof():
            ch = self.peek()
            if ch.isspace() or ch == ']': break
            if ch == '\\': out.append(self.parse_escape())
            else:
                out.append(ch); self.i += 1
        return ''.join(out)

    def read_balanced_parens(self):
        if self.peek() != '(':
            raise SelectorParseError()
        self.i += 1
        start = self.i
        depth = 1
        quote = None
        esc = False
        while not self.eof():
            ch = self.s[self.i]
            if esc:
                esc = False; self.i += 1; continue
            if ch == '\\':
                esc = True; self.i += 1; continue
            if quote:
                if ch == quote: quote = None
                self.i += 1; continue
            if ch in ('"', "'"):
                quote = ch; self.i += 1; continue
            if ch == '(':
                depth += 1
            elif ch == ')':
                depth -= 1
                if depth == 0:
                    arg = self.s[start:self.i]
                    self.i += 1
                    return arg
            self.i += 1
        raise SelectorParseError()

    def parse_pseudo(self):
        if self.peek() != ':': raise SelectorParseError()
        self.i += 1
        if self.peek() == ':':
            raise SelectorParseError()
        name = self.parse_ident(required=True).lower()
        arg = None
        if self.peek() == '(':
            arg = self.read_balanced_parens()
        supported_noarg = {
            'root','scope','empty','first-child','last-child','only-child',
            'first-of-type','last-of-type','only-of-type','link','any-link','visited',
            'hover','active','focus','enabled','disabled','checked'
        }
        supported_func = {'not','nth-child','nth-last-child','nth-of-type','nth-last-of-type'}
        if arg is None:
            if name not in supported_noarg:
                raise SelectorParseError()
            return (name, None)
        else:
            if name not in supported_func:
                raise SelectorParseError()
            if name == 'not':
                # The selector crate version here accepts a single simple selector,
                # not selector lists or combinators in :not().
                if top_level_contains(arg, ',') or top_level_has_combinator(arg):
                    raise SelectorParseError()
                p = CSSParser(arg.strip())
                parts = p.parse_complex(stop_chars=set())
                if not p.eof() or len(parts) != 1:
                    raise SelectorParseError()
                return ('not', parts[0][1])
            return (name, parse_nth(arg))


def top_level_contains(s, char):
    depth = 0; quote = None; esc = False
    for c in s:
        if esc: esc = False; continue
        if c == '\\': esc = True; continue
        if quote:
            if c == quote: quote = None
            continue
        if c in ('"', "'"):
            quote = c; continue
        if c in '([': depth += 1
        elif c in ')]': depth -= 1
        elif depth == 0 and c == char: return True
    return False

def top_level_has_combinator(s):
    depth = 0; quote = None; esc = False
    prev_nonspace = ''
    saw_token = False
    for idx,c in enumerate(s):
        if esc: esc = False; prev_nonspace = c; continue
        if c == '\\': esc = True; continue
        if quote:
            if c == quote: quote = None
            prev_nonspace = c; continue
        if c in ('"', "'"):
            quote = c; prev_nonspace = c; continue
        if c in '([':
            depth += 1; prev_nonspace = c; continue
        if c in ')]':
            depth -= 1; prev_nonspace = c; continue
        if depth == 0:
            if c in ('>','+','~'):
                return True
            if c.isspace():
                # whitespace between two simple-selector tokens is a combinator;
                # whitespace around a single simple selector is not.
                rest = s[idx:].strip()
                if saw_token and rest:
                    return True
            else:
                saw_token = True
        if not c.isspace(): prev_nonspace = c
    return False

def parse_selector(s):
    p = CSSParser(s)
    return p.parse_selector_list()


def parse_nth(arg):
    s = ''.join(arg.lower().split())
    if s == 'odd': return (2,1)
    if s == 'even': return (2,0)
    if 'n' not in s:
        try: return (0, int(s))
        except Exception: raise SelectorParseError()
    before, after = s.split('n',1)
    if before in ('','+'):
        a = 1
    elif before == '-':
        a = -1
    else:
        try: a = int(before)
        except Exception: raise SelectorParseError()
    if after == '':
        b = 0
    else:
        try: b = int(after)
        except Exception: raise SelectorParseError()
    return (a,b)


def element_children(node):
    return [c for c in (node.parent.children if node.parent else []) if c.kind == 'element']

def previous_element_sibling(node):
    if not node.parent: return None
    prev = None
    for c in node.parent.children:
        if c is node: return prev
        if c.kind == 'element': prev = c
    return None

def previous_element_siblings(node):
    if not node.parent: return []
    out = []
    for c in node.parent.children:
        if c is node: break
        if c.kind == 'element': out.append(c)
    return out

def parent_element(node):
    p = node.parent
    return p if p is not None and p.kind == 'element' else None

def elem_index(node, of_type=False, from_end=False):
    if not node.parent: return 0
    sibs = [c for c in node.parent.children if c.kind == 'element' and (not of_type or c.tag.lower() == node.tag.lower())]
    if from_end:
        sibs = list(reversed(sibs))
    try: return sibs.index(node) + 1
    except ValueError: return 0

def nth_matches(idx, ab):
    a,b = ab
    if idx <= 0: return False
    if a == 0: return idx == b
    if a > 0:
        return idx >= b and (idx - b) % a == 0
    return idx <= b and (b - idx) % (-a) == 0


def match_attr(value, op, target, flag):
    if op is None: return True
    v = value; t = target
    if flag == 'i':
        v = v.lower(); t = t.lower()
    if op == '=': return v == t
    if op == '~=': return t in v.split()
    if op == '|=': return v == t or v.startswith(t + '-')
    if op == '^=': return v.startswith(t)
    if op == '$=': return v.endswith(t)
    if op == '*=': return t in v
    return False


def compound_matches(node, comp, scope_root=None):
    if node.kind != 'element': return False
    if comp.get('never'): return False
    tag = comp.get('tag')
    if tag is not None and node.tag.lower() != tag.lower():
        return False
    for ident in comp['ids']:
        if node.attrs.get('id') != ident:
            return False
    for cls in comp['classes']:
        if cls not in node.attrs.get('class','').split():
            return False
    for name, op, value, flag in comp['attrs']:
        # HTML attribute names are ASCII-case-insensitive.
        val = None
        for k,v in node.attrs.items():
            if k.lower() == name.lower():
                val = v; break
        if val is None or not match_attr(val, op, value, flag):
            return False
    for pname, arg in comp['pseudos']:
        if pname == 'root':
            if not (node.tag.lower() == 'html' and node.parent is not None and node.parent.kind == 'document'):
                return False
        elif pname == 'scope':
            if scope_root is not None:
                if node is not scope_root: return False
            elif not (node.tag.lower() == 'html' and node.parent is not None and node.parent.kind == 'document'):
                return False
        elif pname == 'empty':
            for c in node.children:
                if c.kind == 'element': return False
                if c.kind == 'text' and c.data != '': return False
        elif pname == 'first-child':
            if elem_index(node) != 1: return False
        elif pname == 'last-child':
            if elem_index(node, from_end=True) != 1: return False
        elif pname == 'only-child':
            if elem_index(node) != 1 or elem_index(node, from_end=True) != 1: return False
        elif pname == 'first-of-type':
            if elem_index(node, of_type=True) != 1: return False
        elif pname == 'last-of-type':
            if elem_index(node, of_type=True, from_end=True) != 1: return False
        elif pname == 'only-of-type':
            if elem_index(node, of_type=True) != 1 or elem_index(node, of_type=True, from_end=True) != 1: return False
        elif pname == 'nth-child':
            if not nth_matches(elem_index(node), arg): return False
        elif pname == 'nth-last-child':
            if not nth_matches(elem_index(node, from_end=True), arg): return False
        elif pname == 'nth-of-type':
            if not nth_matches(elem_index(node, of_type=True), arg): return False
        elif pname == 'nth-last-of-type':
            if not nth_matches(elem_index(node, of_type=True, from_end=True), arg): return False
        elif pname in ('link','any-link'):
            if not (node.tag.lower() in LINK_HREF_TAGS and 'href' in node.attrs): return False
        elif pname in ('visited','hover','active','focus','enabled','disabled','checked'):
            return False
        elif pname == 'not':
            if compound_matches(node, arg, scope_root=scope_root): return False
        else:
            return False
    return True


def complex_matches(node, parts, scope_root=None):
    def rec(n, idx):
        comb, comp = parts[idx]
        if not compound_matches(n, comp, scope_root=scope_root):
            return False
        if idx == 0:
            return True
        comb_to_prev = parts[idx][0]
        if comb_to_prev == ' ':
            a = parent_element(n)
            while a is not None:
                if rec(a, idx-1): return True
                a = parent_element(a)
            return False
        if comb_to_prev == '>':
            p = parent_element(n)
            return p is not None and rec(p, idx-1)
        if comb_to_prev == '+':
            p = previous_element_sibling(n)
            return p is not None and rec(p, idx-1)
        if comb_to_prev == '~':
            for s in reversed(previous_element_siblings(n)):
                if rec(s, idx-1): return True
            return False
        # Should not happen for idx>0, but be permissive.
        return False
    return rec(node, len(parts)-1)


def iter_elements(node, include_self=False):
    if include_self and node.kind == 'element':
        yield node
    for c in node.children:
        if c.kind == 'element':
            yield c
            yield from iter_elements(c, include_self=False)

def select_nodes(root, selector_text, scoped=False):
    selectors = parse_selector(selector_text)
    if root.kind == 'document':
        candidates = list(iter_elements(root, include_self=False))
        scope_root = None
    else:
        candidates = list(iter_elements(root, include_self=True))
        scope_root = root if scoped else None
    out = []
    for el in candidates:
        if any(complex_matches(el, sel, scope_root=scope_root) for sel in selectors):
            out.append(el)
    return out

# ---------------- serialization / output ----------------

def escape_text(s):
    # html5ever-style escaping used by kuchiki's serializer for text nodes.
    return (s.replace('&','&amp;')
             .replace('\u00a0','&nbsp;')
             .replace('<','&lt;')
             .replace('>','&gt;'))

def escape_attr(s):
    return (s.replace('&','&amp;')
             .replace('\u00a0','&nbsp;')
             .replace('"','&quot;'))

def valid_base_url(url):
    if not url:
        return None
    try:
        p = urlparse(url)
    except Exception:
        return None
    if not p.scheme:
        return None
    if p.scheme in ('http','https') and not p.netloc:
        return None
    return url

def resolve_href(base, href):
    if not base:
        return href
    try:
        return urljoin(base, href)
    except Exception:
        return href

def attr_string(node, base_url=None, top=False):
    parts = []
    for k in sorted(node.attrs.keys()):
        v = node.attrs[k]
        if top and k == 'href' and node.tag.lower() in LINK_HREF_TAGS and base_url:
            v = resolve_href(base_url, v)
        parts.append(f'{k}="{escape_attr(v)}"')
    return (" " + " ".join(parts)) if parts else ""

def serialize(node, base_url=None, top=False, parent_tag=None):
    if node.kind == 'text':
        if parent_tag in ('script','style'):
            return node.data
        return escape_text(node.data)
    if node.kind == 'comment':
        return '<!--' + node.data + '-->'
    if node.kind == 'document':
        return ''.join(serialize(c, base_url=base_url, parent_tag=None) for c in node.children)
    if node.kind == 'element':
        tag = node.tag
        s = '<' + tag + attr_string(node, base_url=base_url, top=top) + '>'
        if tag.lower() in VOID_TAGS:
            return s
        s += ''.join(serialize(c, base_url=base_url, top=False, parent_tag=tag.lower()) for c in node.children)
        s += '</' + tag + '>'
        return s
    return ''

BLOCK_TAGS = {
    'html','head','body','div','p','ul','ol','li','table','thead','tbody','tfoot','tr','td','th',
    'section','article','nav','aside','header','footer','main','form','blockquote','pre','h1','h2',
    'h3','h4','h5','h6','dl','dt','dd','script','style','br','hr','img','meta','link'
}

def pretty_serialize(node, base_url=None, top=True, depth=0, parent_tag=None):
    # This approximates htmlq's pretty mode: two-space indentation with extra
    # line breaks around block-level elements. Inline-only selected elements are
    # left compact, matching common htmlq behavior for spans/links.
    if node.kind != 'element':
        return serialize(node, base_url=base_url, top=top, parent_tag=parent_tag)
    tag = node.tag.lower()
    if tag in VOID_TAGS:
        return '  '*depth + serialize(node, base_url=base_url, top=top, parent_tag=parent_tag)
    elem_children = [c for c in node.children if c.kind == 'element']
    blocky = tag in BLOCK_TAGS or any(c.kind == 'element' and c.tag.lower() in BLOCK_TAGS for c in node.children)
    if not elem_children and all(c.kind != 'comment' for c in node.children):
        # Simple text element: start tag and text on the same line, close on a
        # following line for block-ish nodes, compact for inline nodes.
        compact = serialize(node, base_url=base_url, top=top, parent_tag=parent_tag)
        if top and tag not in BLOCK_TAGS:
            return compact
        if tag in BLOCK_TAGS and node.children:
            open_tag = '<' + node.tag + attr_string(node, base_url=base_url, top=top) + '>'
            text = ''.join(serialize(c, base_url=base_url, parent_tag=tag) for c in node.children)
            return '  '*depth + open_tag + text + '\n' + '  '*depth + '</' + node.tag + '>'
        return '  '*depth + compact
    if top and not blocky:
        return serialize(node, base_url=base_url, top=top, parent_tag=parent_tag)
    lines = []
    lines.append('  '*depth + '<' + node.tag + attr_string(node, base_url=base_url, top=top) + '>')
    for c in node.children:
        if c.kind == 'text':
            if c.data == '':
                continue
            if c.data.strip() == '':
                if '\n' in c.data:
                    lines.append('')
                else:
                    # keep small whitespace inline-ish by appending to previous line
                    if lines: lines[-1] += escape_text(c.data)
                continue
            text = serialize(c, base_url=base_url, parent_tag=tag)
            if '\n' in text:
                for tline in text.splitlines():
                    if tline:
                        lines.append('  '*(depth+1)+tline)
                    else:
                        lines.append('')
            else:
                lines.append('  '*(depth+1)+text)
        elif c.kind == 'comment':
            if lines:
                lines[-1] += serialize(c, base_url=base_url, parent_tag=tag)
            else:
                lines.append('  '*(depth+1)+serialize(c, base_url=base_url, parent_tag=tag))
        elif c.kind == 'element':
            lines.append(pretty_serialize(c, base_url=base_url, top=False, depth=depth+1, parent_tag=tag))
    lines.append('  '*depth + '</' + node.tag + '>')
    return '\n'.join(lines)


def text_descendants(node):
    out = []
    def walk(n):
        for c in n.children:
            if c.kind == 'text': out.append(c.data)
            elif c.kind == 'element': walk(c)
    walk(node)
    return out


def first_base_href(doc):
    try:
        bases = select_nodes(doc, 'base')
    except Exception:
        bases = []
    if not bases:
        return None
    return bases[0].attrs.get('href')

# ---------------- CLI ----------------
HELP = """htmlq 0.4.0
Michael Maclean <michael@mgdm.net>
Runs CSS selectors on HTML

USAGE:
    executable [FLAGS] [OPTIONS] [--] [selector]...

FLAGS:
    -B, --detect-base          Try to detect the base URL from the <base> tag in the document. If not found, default to
                               the value of --base, if supplied
    -h, --help                 Prints help information
    -w, --ignore-whitespace    When printing text nodes, ignore those that consist entirely of whitespace
    -p, --pretty               Pretty-print the serialised output
    -t, --text                 Output only the contents of text nodes inside selected elements
    -V, --version              Prints version information

OPTIONS:
    -a, --attribute <attribute>         Only return this attribute (if present) from selected elements
    -b, --base <base>                   Use this URL as the base for links
    -f, --filename <FILE>               The input file. Defaults to stdin
    -o, --output <FILE>                 The output file. Defaults to stdout
    -r, --remove-nodes <SELECTOR>...    Remove nodes matching this expression before output. May be specified multiple
                                        times

ARGS:
    <selector>...    The CSS expression to select [default: html]
"""

LONG_OPTS = {
    'attribute':'a','base':'b','filename':'f','output':'o','remove-nodes':'r',
    'help':'h','version':'V','text':'t','pretty':'p','ignore-whitespace':'w','detect-base':'B'
}
OPT_NAMES = {'a':'attribute','b':'base','f':'filename','o':'output','r':'remove-nodes'}
FLAG_CHARS = set('BhVtpw')
VALUE_CHARS = set('abfor')

class CLIError(Exception):
    def __init__(self, msg, usage=None):
        self.msg = msg; self.usage = usage

def clap_error(msg, usage):
    sys.stderr.write(f"error: {msg}\n\nUSAGE:\n    executable {usage}\n\nFor more information try --help\n")
    sys.exit(1)

def parse_args(argv):
    opts = {'B':False,'h':False,'V':False,'t':False,'p':False,'w':False,
            'a':None,'b':None,'f':None,'o':None,'r':[],'selector':[]}
    seen_single = set()
    i = 0; endopts = False
    while i < len(argv):
        arg = argv[i]
        if endopts or arg == '-' or not arg.startswith('-'):
            opts['selector'].append(arg); i += 1; continue
        if arg == '--':
            endopts = True; i += 1; continue
        if arg.startswith('--'):
            body = arg[2:]
            val = None
            if '=' in body:
                body, val = body.split('=',1)
            if body not in LONG_OPTS:
                clap_error(f"Found argument '{arg}' which wasn't expected, or isn't valid in this context", "[FLAGS] [OPTIONS] [--] [selector]...")
            ch = LONG_OPTS[body]
            if ch in FLAG_CHARS:
                if val is not None:
                    clap_error(f"Found argument '{arg}' which wasn't expected, or isn't valid in this context", "[FLAGS] [OPTIONS] [--] [selector]...")
                opts[ch] = True; i += 1; continue
            if val is None:
                if i+1 >= len(argv):
                    clap_error(f"The argument '--{body} <{placeholder(ch)}>' requires a value but none was supplied", f"--{body} <{placeholder(ch)}>" )
                val = argv[i+1]; i += 2
            else:
                i += 1
            if ch == 'r':
                opts['r'].append(val)
            else:
                if ch in seen_single:
                    clap_error(f"The argument '--{body} <{placeholder(ch)}>' was provided more than once, but cannot be used multiple times", f"--{body} <{placeholder(ch)}>" )
                seen_single.add(ch); opts[ch] = val
            continue
        # short cluster
        cluster = arg[1:]
        if cluster == '':
            opts['selector'].append(arg); i += 1; continue
        j = 0
        consumed_next = False
        while j < len(cluster):
            ch = cluster[j]
            if ch in FLAG_CHARS:
                opts[ch] = True; j += 1; continue
            if ch in VALUE_CHARS:
                if j+1 < len(cluster):
                    val = cluster[j+1:]
                    j = len(cluster)
                else:
                    if i+1 >= len(argv):
                        long = OPT_NAMES[ch]
                        clap_error(f"The argument '--{long} <{placeholder(ch)}>' requires a value but none was supplied", f"--{long} <{placeholder(ch)}>" )
                    val = argv[i+1]
                    consumed_next = True
                    j = len(cluster)
                if ch == 'r':
                    opts['r'].append(val)
                else:
                    if ch in seen_single:
                        long = OPT_NAMES[ch]
                        clap_error(f"The argument '--{long} <{placeholder(ch)}>' was provided more than once, but cannot be used multiple times", f"--{long} <{placeholder(ch)}>" )
                    seen_single.add(ch); opts[ch] = val
                break
            clap_error(f"Found argument '-{ch}' which wasn't expected, or isn't valid in this context", "[FLAGS] [OPTIONS] [--] [selector]...")
        i += 2 if consumed_next else 1
    return opts

def placeholder(ch):
    return {'a':'attribute','b':'base','f':'FILE','o':'FILE','r':'SELECTOR'}.get(ch,'value')

def panic_parse_selector():
    pid = os.getpid()
    sys.stderr.write(f"\nthread 'main' ({pid}) panicked at src/main.rs:221:10:\n")
    sys.stderr.write("Failed to parse CSS selector: ()\n")
    sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.exit(101)

def panic_file(kind, path, line=196):
    pid = os.getpid()
    sys.stderr.write(f"\nthread 'main' ({pid}) panicked at src/main.rs:{line}:37:\n")
    if kind == 'input':
        sys.stderr.write(f"should have opened input file: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}\n")
    else:
        sys.stderr.write(f"should have opened output file: {path}\n")
    sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.exit(101)


def main(argv):
    opts = parse_args(argv)
    if opts['h']:
        sys.stdout.write(HELP)
        return 0
    if opts['V']:
        sys.stdout.write(VERSION + "\n")
        return 0
    try:
        if opts['f'] is not None:
            with open(opts['f'], 'r', encoding='utf-8') as f:
                data = f.read()
        else:
            data = sys.stdin.read()
    except FileNotFoundError:
        panic_file('input', opts['f'])
    except Exception as e:
        pid = os.getpid()
        sys.stderr.write(f"\nthread 'main' ({pid}) panicked at src/main.rs:196:37:\nshould have opened input file: {e}\n")
        sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
        return 101

    doc = parse_html(data)
    base_url = None
    explicit_base = valid_base_url(opts['b']) if opts['b'] is not None else None
    if opts['B']:
        detected = valid_base_url(first_base_href(doc))
        base_url = detected or explicit_base
    else:
        base_url = explicit_base

    selector_text = ' '.join(opts['selector']) if opts['selector'] else 'html'
    try:
        selected = select_nodes(doc, selector_text)
    except SelectorParseError:
        panic_parse_selector()

    if opts['r']:
        filtered = []
        for n in selected:
            skip = False
            for rsel in opts['r']:
                try:
                    if select_nodes(n, rsel, scoped=True):
                        skip = True; break
                except SelectorParseError:
                    continue
            if not skip:
                filtered.append(n)
        selected = filtered

    out_parts = []
    attr = opts['a']
    if attr is not None:
        for n in selected:
            if attr in n.attrs:
                val = n.attrs[attr]
                if attr == 'href' and n.tag.lower() in LINK_HREF_TAGS and base_url:
                    val = resolve_href(base_url, val)
                out_parts.append(val + '\n')
    elif opts['t']:
        for n in selected:
            texts = text_descendants(n)
            if opts['w']:
                for t in texts:
                    if t.strip() != '':
                        out_parts.append(t + '\n')
                out_parts.append('\n')
            else:
                out_parts.append(''.join(texts) + '\n')
    else:
        for n in selected:
            if opts['p']:
                s = pretty_serialize(n, base_url=base_url, top=True, depth=0)
                # htmlq's pretty mode starts block selections on a fresh line.
                if n.tag.lower() in BLOCK_TAGS:
                    out_parts.append('\n' + s + '\n')
                else:
                    out_parts.append(s + '\n')
            else:
                out_parts.append(serialize(n, base_url=base_url, top=True) + '\n')
    output = ''.join(out_parts)
    if opts['o'] is not None:
        try:
            with open(opts['o'], 'w', encoding='utf-8') as f:
                f.write(output)
        except Exception:
            panic_file('output', opts['o'], line=205)
    else:
        sys.stdout.write(output)
    return 0

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
