HELP = """htmlq 0.4.0
Michael Maclean <michael@mgdm.net>
Runs CSS selectors on HTML

USAGE:
    executable [FLAGS] [OPTIONS] [--] [selector]...

FLAGS:
    -B, --detect-base          Try to detect the base URL from the <base> tag in the document. If not found, default to
                               the value of --base, if supplied
    -h, --help                 Prints help information
    -w, --ignore-whitespace    When printing text nodes, ignore those that consist entirely of whitespace
    -p, --pretty               Pretty-print the serialised output
    -t, --text                 Output only the contents of text nodes inside selected elements
    -V, --version              Prints version information

OPTIONS:
    -a, --attribute <attribute>         Only return this attribute (if present) from selected elements
    -b, --base <base>                   Use this URL as the base for links
    -f, --filename <FILE>               The input file. Defaults to stdin
    -o, --output <FILE>                 The output file. Defaults to stdout
    -r, --remove-nodes <SELECTOR>...    Remove nodes matching this expression before output. May be specified multiple
                                        times

ARGS:
    <selector>...    The CSS expression to select [default: html]
"""

LONG_OPTS = {
    'attribute':'a','base':'b','filename':'f','output':'o','remove-nodes':'r',
    'help':'h','version':'V','text':'t','pretty':'p','ignore-whitespace':'w','detect-base':'B'
}
OPT_NAMES = {'a':'attribute','b':'base','f':'filename','o':'output','r':'remove-nodes'}
FLAG_CHARS = set('BhVtpw')
VALUE_CHARS = set('abfor')

class CLIError(Exception):
    def __init__(self, msg, usage=None):
        self.msg = msg; self.usage = usage

def clap_error(msg, usage):
    sys.stderr.write(f"error: {msg}\n\nUSAGE:\n    executable {usage}\n\nFor more information try --help\n")
    sys.exit(1)

def parse_args(argv):
    opts = {'B':False,'h':False,'V':False,'t':False,'p':False,'w':False,
            'a':None,'b':None,'f':None,'o':None,'r':[],'selector':[]}
    seen_single = set()
    i = 0; endopts = False
    while i < len(argv):
        arg = argv[i]
        if endopts or arg == '-' or not arg.startswith('-'):
            opts['selector'].append(arg); i += 1; continue
        if arg == '--':
            endopts = True; i += 1; continue
        if arg.startswith('--'):
            body = arg[2:]
            val = None
            if '=' in body:
                body, val = body.split('=',1)
            if body not in LONG_OPTS:
                clap_error(f"Found argument '{arg}' which wasn't expected, or isn't valid in this context", "[FLAGS] [OPTIONS] [--] [selector]...")
            ch = LONG_OPTS[body]
            if ch in FLAG_CHARS:
                if val is not None:
                    clap_error(f"Found argument '{arg}' which wasn't expected, or isn't valid in this context", "[FLAGS] [OPTIONS] [--] [selector]...")
                opts[ch] = True; i += 1; continue
            if val is None:
                if i+1 >= len(argv):
                    clap_error(f"The argument '--{body} <{placeholder(ch)}>' requires a value but none was supplied", f"--{body} <{placeholder(ch)}>" )
                val = argv[i+1]; i += 2
            else:
                i += 1
            if ch == 'r':
                opts['r'].append(val)
            else:
                if ch in seen_single:
                    clap_error(f"The argument '--{body} <{placeholder(ch)}>' was provided more than once, but cannot be used multiple times", f"--{body} <{placeholder(ch)}>" )
                seen_single.add(ch); opts[ch] = val
            continue
        # short cluster
        cluster = arg[1:]
        if cluster == '':
            opts['selector'].append(arg); i += 1; continue
        j = 0
        consumed_next = False
        while j < len(cluster):
            ch = cluster[j]
            if ch in FLAG_CHARS:
                opts[ch] = True; j += 1; continue
            if ch in VALUE_CHARS:
                if j+1 < len(cluster):
                    val = cluster[j+1:]
                    j = len(cluster)
                else:
                    if i+1 >= len(argv):
                        long = OPT_NAMES[ch]
                        clap_error(f"The argument '--{long} <{placeholder(ch)}>' requires a value but none was supplied", f"--{long} <{placeholder(ch)}>" )
                    val = argv[i+1]
                    consumed_next = True
                    j = len(cluster)
                if ch == 'r':
                    opts['r'].append(val)
                else:
                    if ch in seen_single:
                        long = OPT_NAMES[ch]
                        clap_error(f"The argument '--{long} <{placeholder(ch)}>' was provided more than once, but cannot be used multiple times", f"--{long} <{placeholder(ch)}>" )
                    seen_single.add(ch); opts[ch] = val
                break
            clap_error(f"Found argument '-{ch}' which wasn't expected, or isn't valid in this context", "[FLAGS] [OPTIONS] [--] [selector]...")
        i += 2 if consumed_next else 1
    return opts

def placeholder(ch):
    return {'a':'attribute','b':'base','f':'FILE','o':'FILE','r':'SELECTOR'}.get(ch,'value')

def panic_parse_selector():
    pid = os.getpid()
    sys.stderr.write(f"\nthread 'main' ({pid}) panicked at src/main.rs:221:10:\n")
    sys.stderr.write("Failed to parse CSS selector: ()\n")
    sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.exit(101)

def panic_file(kind, path, line=196):
    pid = os.getpid()
    sys.stderr.write(f"\nthread 'main' ({pid}) panicked at src/main.rs:{line}:37:\n")
    if kind == 'input':
        sys.stderr.write(f"should have opened input file: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}\n")
    else:
        sys.stderr.write(f"should have opened output file: {path}\n")
    sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.exit(101)


def main(argv):
    opts = parse_args(argv)
    if opts['h']:
        sys.stdout.write(HELP)
        return 0
    if opts['V']:
        sys.stdout.write(VERSION + "\n")
        return 0
    try:
        if opts['f'] is not None:
            with open(opts['f'], 'r', encoding='utf-8') as f:
                data = f.read()
        else:
            data = sys.stdin.read()
    except FileNotFoundError:
        panic_file('input', opts['f'])
    except Exception as e:
        pid = os.getpid()
        sys.stderr.write(f"\nthread 'main' ({pid}) panicked at src/main.rs:196:37:\nshould have opened input file: {e}\n")
        sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
        return 101

    doc = parse_html(data)
    base_url = None
    explicit_base = valid_base_url(opts['b']) if opts['b'] is not None else None
    if opts['B']:
        detected = valid_base_url(first_base_href(doc))
        base_url = detected or explicit_base
    else:
        base_url = explicit_base

    selector_text = ' '.join(opts['selector']) if opts['selector'] else 'html'
    try:
        selected = select_nodes(doc, selector_text)
    except SelectorParseError:
        panic_parse_selector()

    if opts['r']:
        filtered = []
        for n in selected:
            skip = False
            for rsel in opts['r']:
                try:
                    if select_nodes(n, rsel, scoped=True):
                        skip = True; break
                except SelectorParseError:
                    continue
            if not skip:
                filtered.append(n)
        selected = filtered

    out_parts = []
    attr = opts['a']
    if attr is not None:
        for n in selected:
            if attr in n.attrs:
                val = n.attrs[attr]
                if attr == 'href' and n.tag.lower() in LINK_HREF_TAGS and base_url:
                    val = resolve_href(base_url, val)
                out_parts.append(val + '\n')
    elif opts['t']:
        for n in selected:
            texts = text_descendants(n)
            if opts['w']:
                for t in texts:
                    if t.strip() != '':
                        out_parts.append(t + '\n')
                out_parts.append('\n')
            else:
                out_parts.append(''.join(texts) + '\n')
    else:
        for n in selected:
            if opts['p']:
                s = pretty_serialize(n, base_url=base_url, top=True, depth=0)
                # htmlq's pretty mode starts block selections on a fresh line.
                if n.tag.lower() in BLOCK_TAGS:
                    out_parts.append('\n' + s + '\n')
                else:
                    out_parts.append(s + '\n')
            else:
                out_parts.append(serialize(n, base_url=base_url, top=True) + '\n')
    output = ''.join(out_parts)
    if opts['o'] is not None:
        try:
            with open(opts['o'], 'w', encoding='utf-8') as f:
                f.write(output)
        except Exception:
            panic_file('output', opts['o'], line=205)
    else:
        sys.stdout.write(output)
    return 0

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
